    16	fn parse_distance(value: &str) -> Result<f64, String> {
    17	    match value.parse::<f64>() {
    18	        Ok(km) if km.is_finite() && km >= 0.0 => Ok(km),
    19	        _ => Err(format!(
    20	            "invalid --max-distance '{value}': expected a non-negative number of kilometers"
    21	        )),
    22	    }
    23	}
    24	
    25	fn parse_search_args(args: &[String]) -> Result<SearchFilter, String> {
    26	    let mut filter = SearchFilter::new();
    27	    let (mut name, mut distance, mut difficulty) = (false, false, false);
    28	    let mut iter = args.iter().peekable();
    29	    while let Some(flag) = iter.next() {
    30	        let seen = match flag.as_str() {
    31	            "--name" => &mut name,
    32	            "--max-distance" => &mut distance,
    33	            "--difficulty" => &mut difficulty,
    34	            other => return Err(format!("unknown argument '{other}'")),
    35	        };
    36	        if *seen {
    37	            return Err(format!("{flag} was given more than once"));
    38	        }
    39	        *seen = true;
    40	        let value = iter
    41	            .next_if(|next| !matches!(next.as_str(), "--name" | "--max-distance" | "--difficulty"))
    42	            .ok_or_else(|| format!("{flag} requires a value"))?;
    43	        filter = match flag.as_str() {
    44	            "--name" => filter.name_contains(value.as_str()),
    45	            "--max-distance" => filter.max_distance_km(parse_distance(value)?),
    46	            _ => filter.difficulty(parse_difficulty(value)?),
    47	        };
    48	    }
    49	    Ok(filter)
    50	}
    51	
    52	fn fail(message: &str) -> ! {
    53	    eprintln!("error: {message}\n{USAGE}");
    54	    std::process::exit(2);
    55	}
    56	
    57	fn main() {
    58	    let args: Vec<String> = std::env::args().skip(1).collect();
    59	    match args.split_first() {
    60	        Some((command, rest)) if command == "list" && rest.is_empty() => {
    61	            for route in catalogue() {
    62	                println!("{}", display_route(&route));
    63	            }
    64	        }
    65	        Some((command, rest)) if command == "search" => {
    66	            let filter = parse_search_args(rest).unwrap_or_else(|message| fail(&message));
    67	            let routes = catalogue();
    68	            for route in search(&routes, &filter) {
    69	                println!("{}", display_route(route));
    70	            }
    71	        }
    72	        Some((command, _)) if command == "list" => fail("list takes no arguments"),
    73	        Some((command, _)) => fail(&format!("unknown command '{command}'")),
    74	        None => fail("missing command"),
    75	    }
    76	}
